#!/usr/bin/env bash
# Usage: tests/fixtures/make-long-session.sh <depth-tokens> <out.json>
set -euo pipefail
cd "$(dirname "$0")/../.."

DEPTH="$1"
OUT="$2"
PIN=2939b10ac049ee60498cce590d41019fcbb969ee
BIG=tests/fixtures/agent-session-big.json
NO_TOOLS="Answer from the history above, without calling any tool."

WORK=$(mktemp -d)
trap 'rm -rf "$WORK"' EXIT

git log -p --reverse --no-color "$PIN" > "$WORK/history"
haystack=$(head -c $((DEPTH * 3)) "$WORK/history" | iconv -c -f utf-8 -t utf-8)

plant() {
    local pct="$1" fact="$2" at
    at=$(( ${#haystack} * pct / 100 ))
    local rest="${haystack:at}"
    local to_eol="${rest%%$'\n'*}"
    at=$(( at + ${#to_eol} + 1 ))
    haystack="${haystack:0:at}${fact}"$'\n'"${haystack:at}"
}

F10="Release note: the ledger-sync job's maintenance window is Thursday 03:40 UTC."
F30="Ops note: Priya Raman owns the billing-ledger service."
F50="Config note: the staging cache bucket is named amber-otter-5512."
F70="Ops note: Priya Raman's escalation code is ZEBRA-0417."
F90="Ops note: the fallback LLM endpoint listens on port 8931."
plant 90 "$F90"; plant 70 "$F70"; plant 50 "$F50"; plant 30 "$F30"; plant 10 "$F10"

quarter=$(( ${#haystack} / 4 ))
for i in 1 2 3; do
    rest="${haystack:quarter}"
    after_eol="${rest#*$'\n'}"
    cut=$(( quarter + ${#rest} - ${#after_eol} ))
    printf '%s' "${haystack:0:cut}" > "$WORK/page$i"
    haystack="${haystack:cut}"
done
printf '%s' "$haystack" > "$WORK/page4"

jq -n --slurpfile big "$BIG" --arg depth "$DEPTH" --arg pin "$PIN" --arg no_tools "$NO_TOOLS" \
      --rawfile p1 "$WORK/page1" --rawfile p2 "$WORK/page2" \
      --rawfile p3 "$WORK/page3" --rawfile p4 "$WORK/page4" \
      --arg f10 "$F10" --arg f50 "$F50" --arg f90 "$F90" '
def call(id; name; args): {role: "assistant", content: "",
    tool_calls: [{id: id, type: "function", function: {name: name, arguments: (args | tojson)}}]};
def page(n; content): {id: "t\(n)-history-page", expect: "tool_call",
    user: "Show me page \(n) of 4 of the acme/llm-server commit history, with diffs.",
    replay_assistant: call("call_p\(n)"; "github_acme_list_commits"; {owner: "acme", repo: "llm-server", page: n}),
    replay_tool: {role: "tool", tool_call_id: "call_p\(n)", content: content}};
def ask(id; q; want; answer): {id: id, expect: "content", user: "\(q) \($no_tools)",
    expect_contains: want, replay_assistant: {role: "assistant", content: answer}};
{
  schema: 1,
  description: "Long-context session at ~\($depth) tokens of history from \($pin). Generated by tests/fixtures/make-long-session.sh; not committed.",
  system: $big[0].system,
  tools: $big[0].tools,
  turns: [
    page(1; $p1), page(2; $p2), page(3; $p3), page(4; $p4),
    (ask("q-depth-10"; "When is the ledger-sync job'"'"'s maintenance window?"; ["Thursday", "03:40"];
         "Thursday 03:40 UTC.") + {depth_pct: 10, fact: $f10}),
    (ask("q-depth-50"; "What is the staging cache bucket named?"; ["amber-otter-5512"];
         "amber-otter-5512.") + {depth_pct: 50, fact: $f50}),
    (ask("q-depth-90"; "Which port does the fallback LLM endpoint listen on?"; ["8931"];
         "Port 8931.") + {depth_pct: 90, fact: $f90}),
    ask("q-multi"; "List the ledger-sync maintenance window, the staging cache bucket name and the fallback LLM endpoint port.";
        ["03:40", "amber-otter-5512", "8931"]; "Thursday 03:40 UTC; amber-otter-5512; port 8931."),
    ask("q-hop"; "What is the escalation code of whoever owns the billing-ledger service?"; ["ZEBRA-0417"];
        "ZEBRA-0417, Priya Raman'"'"'s."),
    {id: "t-tool-after-long", expect: "tool_call", tools: ["github_globex_search_pull_requests"],
     user: "Now look up which open pull requests in globex/api touch authentication.",
     replay_assistant: call("call_prs"; "github_globex_search_pull_requests"; {query: "repo:globex/api is:pr is:open auth"}),
     replay_tool: {role: "tool", tool_call_id: "call_prs",
                   content: ({total_count: 1, items: [{number: 15, title: "Rate-limit the login endpoint", state: "open"}]} | tojson)}}
  ]
}' > "$OUT"

echo "wrote $OUT: $(jq '.turns | length' "$OUT") turns, $(wc -c < "$OUT" | tr -d ' ') bytes"
